import re, os
def strip_comments(s):
    out=[]; i=0; depth=0
    while i < len(s):
        if depth==0 and s.startswith('/-',i): depth=1; i+=2; continue
        if depth>0:
            if s.startswith('/-',i): depth+=1; i+=2; continue
            if s.startswith('-/',i): depth-=1; i+=2; continue
            out.append('\n' if s[i]=='\n' else ' '); i+=1; continue
        if s.startswith('--',i):
            j=s.find('\n',i); j=len(s) if j<0 else j
            out.append(' '*(j-i)); i=j; continue
        out.append(s[i]); i+=1
    return ''.join(out)
